import{cycleDays,cycleCurves,freshCycleCurves,cycleState,ivfStage,curveValue}from './repro-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const xt=(x,y,s,z=16)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-size="${z}">${esc(s)}</text>`;
const line=(d,c='#b8cfd2',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const dot=(x,y,r=7,c='#edc99d')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
export const reproSVG=(a,label)=>`<svg viewBox="0 0 560 400" role="img" aria-label="${esc(label)}"><defs><radialGradient id="reproEgg"><stop stop-color="#f5dfbb"/><stop offset="1" stop-color="#ba937f"/></radialGradient><linearGradient id="reproOrgan"><stop stop-color="#cda29a"/><stop offset="1" stop-color="#9c7077"/></linearGradient></defs>${a}</svg>`;
function uterus(thickness=7){return `<path d="M285 130q-15-35-50-15m210 15q15-35 50-15M285 130q25 15 80 15t80-15q-12 62-49 96l-14 75h-34l-14-75q-37-34-49-96Z" fill="url(#reproOrgan)" stroke="#e8c8b6" stroke-width="3"/>`+line('M309 155q56 25 112 0q-11 38-41 60l-15 61-15-61q-30-22-41-60Z','#e7b5a3',thickness);}
export function cycleFigure({progress=0,state=''}={}){let f=cycleState(progress),a=xt(280,30,'Ovarian events and uterus-lining changes',20)+`<ellipse cx="125" cy="170" rx="62" ry="45" fill="url(#reproOrgan)" stroke="#dfc6b3" stroke-width="3"/>`+uterus(f.lining)+xt(125,260,'Ovary',18)+xt(365,332,'Uterus lining',18);let phase=f.phase,q=(progress*4)%1;if(phase<2)a+=`<circle cx="125" cy="170" r="${phase===0?8:9+q*13}" fill="url(#reproEgg)" stroke="#f8e1ba" stroke-width="3"/>`;else if(phase===2)a+=dot(185+q*50,155-q*40,10);else a+=dot(125,170,14,'#d8c4a2');a+=line('M190 140q20-25 42-25','#abc4c8',2)+xt(280,371,['Menstruation: lining sheds','FSH supports maturation; lining rebuilds','LH stimulates ovulation','Progesterone supports lining maintenance'][phase],16)+xt(280,395,'Illustrative sequence; real timing varies',12);return reproSVG(a,'Schematic ovary and uterus; '+['menstruation','egg maturation and lining rebuilding','ovulation','lining maintenance'][phase]+'. Not an individual fertility prediction.');}
export function pubertyFigure({progress=0,state=''}={}){let a=xt(280,33,'Separate hormone sources and responses',21);for(let[y,organ,hormone,result]of [[130,'Ovaries','Oestrogen','Puberty-related changes'],[265,'Testes','Testosterone','Sperm production / changes']]){a+=`<ellipse cx="90" cy="${y}" rx="53" ry="34" fill="url(#reproOrgan)"/>`+xt(90,y+65,organ,16)+line(`M150 ${y}H410`)+`<polygon points="${170+progress*220},${y-9} ${179+progress*220},${y} ${170+progress*220},${y+9} ${161+progress*220},${y}" fill="#adcdd0"/>`+xt(285,y-30,hormone,17)+xt(415,y+38,result,13);}return reproSVG(a+xt(280,382,'Hormone signals travel in blood; development varies',14),'Ovaries produce oestrogen; testes produce testosterone; testosterone supports sperm production.');}
export function hormoneGraph({fresh=false,day=null,progress}={}){let curves=fresh?freshCycleCurves:cycleCurves,cols=['#efb39c','#e3cb92','#a6cbd0','#c6b6d1'],dashes=['','7 4','2 4','12 3 2 3'],x=d=>63+(d-1)*16.5,y=v=>300-v*17,a='';[0,5,10].forEach(v=>a+=line(`M63 ${y(v)}H510`,'#536f82',1)+xt(40,y(v)+4,v,14));a+=line('M63 106V300H511');[1,7,14,21,28].forEach(d=>a+=xt(x(d),324,d,15));a+=xt(280,349,'Illustrative day in cycle',15)+`<text x="20" y="210" transform="rotate(-90 20 210)" text-anchor="middle" fill="#f8f6f2" font-size="14">Relative units</text>`;Object.entries(curves).forEach(([name,vals],j)=>{a+=`<polyline points="${vals.map((v,i)=>x(cycleDays[i])+','+y(v)).join(' ')}" fill="none" stroke="${cols[j]}" stroke-width="3" stroke-dasharray="${dashes[j]}"/>`;let lx=105+j%2*245,ly=30+Math.floor(j/2)*30;a+=line(`M${lx-45} ${ly-5}h30`,cols[j],3)+xt(lx+47,ly,name,15);});let cursor=progress===undefined?day:1+progress*27;if(cursor!==null){a+=line(`M${x(cursor)} 107V300`,'#f6e9cb',1);a+=xt(280,379,'Day '+Number(cursor).toFixed(0)+': '+Object.entries(curves).map(([n,c])=>n.slice(0,1)+' '+curveValue(c,cursor).toFixed(1)).join(' · '),14);}else a+=xt(280,379,'Original curves; illustrative units, not clinical concentrations',12);return reproSVG(a,'Original illustrative hormone graph. Days '+cycleDays.join(', ')+'. '+Object.entries(curves).map(([n,c])=>n+': '+c.join(', ')).join('; '));}
export function ivfFigure({progress=0,state=''}={}){let n=ivfStage(progress),a=xt(280,29,'IVF: fertilisation outside the body',22),names=['Hormone stimulation','Egg collection','Laboratory fertilisation','Embryo development','Embryo transfer'];a+=xt(280,72,names[n],20);if(n===4){a+=uterus(10);for(let i=0;i<4;i++)a+=dot(355+i%2*10,182+Math.floor(i/2)*10,6);a+=line('M80 200h220l-9-8m9 8-9 8')+xt(280,357,'Transfer offers a chance, not guaranteed implantation',15);}else{a+=`<ellipse cx="280" cy="230" rx="174" ry="78" fill="#48677b" fill-opacity=".6" stroke="#bdd0d0" stroke-width="4"/><ellipse cx="280" cy="216" rx="174" ry="78" fill="none" stroke="#799ca9" stroke-width="2"/>`;for(let j=0;j<3;j++){let x=180+j*100;if(n<3)a+=`<circle cx="${x}" cy="216" r="${n===0?10+progress*25:20}" fill="url(#reproEgg)" stroke="#f5dfbb" stroke-width="2"/>`;else{for(let k=0;k<8;k++)a+=dot(x+Math.cos(k*Math.PI/4)*13,216+Math.sin(k*Math.PI/4)*13,7);}}if(n===2)for(let j=0;j<3;j++){let x=180+j*100+45-(progress*5%1)*25;a+=dot(x,195,4,'#bad6db')+line(`M${x+3} 195q15-10 21-5`,'#bad6db',2);}a+=xt(280,355,n===3?'Cell division produces early embryos':'Simplified laboratory stages',16);}return reproSVG(a+xt(280,389,'GCSE process summary; not a treatment protocol',13),'IVF stage '+(n+1)+': '+names[n]+'. Egg/sperm/embryo forms are schematic.');}
export function methodFigure({state='pill'}={}){let labels={pill:['Hormonal suppression','Reduced FSH can limit egg maturation'],delivery:['Hormone delivery over time','Injection / implant / patch: formulations differ'],barrier:['Barrier','Reduces sperm reaching an egg'],intrauterine:['Intrauterine methods','Copper IUD differs from hormone-releasing IUS'],spermicide:['Spermicide','Kills or disables sperm'],timing:['Timing-based abstinence','Cycle variation limits calendar certainty'],surgery:['Sterilisation','Interrupts sperm or egg transport']},t=labels[state]||labels.pill;return reproSVG(xt(280,40,t[0],23)+`<rect x="80" y="105" width="400" height="160" rx="26" fill="#3e5d72" stroke="#b3ccd0" stroke-width="2"/>`+line('M130 185h100m100 0h100')+`<rect x="265" y="145" width="30" height="80" rx="9" fill="#d4b499"/>`+xt(280,312,t[1],16)+xt(280,370,'Compare biological action, use demands and circumstances',13),'Mechanism comparison: '+t.join('. '));}
export function evidenceFigure({state=''}={}){if(['transfer','multiple','support','ivf'].includes(state))return reproSVG(xt(280,50,'Fertility treatment: weigh the evidence',22)+xt(280,140,'Chance of pregnancy · success is uncertain',20)+xt(280,215,'Stress, access, surgical/medicine and multiple-birth risks',16)+xt(280,305,'Patient and clinician perspectives can differ',18),'Evaluate fertility treatment benefits, uncertain outcomes and burdens.');if(['timing','puberty'].includes(state))return reproSVG(xt(280,80,'Development and cycle timing vary',23)+xt(280,195,'Textbook sequences explain biological roles',20)+xt(280,280,'They do not predict an individual timetable',19),'Hormones control developmental changes; individual timing varies.');return reproSVG(xt(280,40,'Compare supplied evidence and circumstances',21)+xt(280,130,'Fictional methods A/B: 40 / 10 pregnancies per 1000',17)+xt(280,188,'Proportions: 4% / 1% · difference: 3 percentage points',17)+xt(280,260,'Consider uncertainty, consistent use, access and values',16)+xt(280,330,state==='multiple'?'More embryos can increase multiple-birth risks':'Supplied data do not prescribe an individual choice',16),'Original classroom evidence for method comparison; data are fictional, not clinical product rates.');}
export function reproFigure(w={}){if(w.concealed)return reproSVG(xt(280,195,'Predict, then reveal the evidence',22),'Outcome concealed until prediction');if(w.kind==='ivf-evidence')return evidenceFigure({state:'ivf'});if(w.kind==='graph'||w.kind==='feedback')return hormoneGraph(w);if(w.kind==='puberty')return pubertyFigure(w);if(w.kind==='cycle')return cycleFigure(w);if(w.kind==='ivf')return ivfFigure(w);if(w.kind==='methods')return methodFigure(w);return evidenceFigure(w);}
export const reproAssessmentFigure=f=>reproFigure({kind:f.diagram,fresh:!!f.fresh});
